	activeRequest = controller;
	let timedOut = false;
	const stopped = new Promise((_, reject) =>
		controller.signal.addEventListener(
			"abort",
			() =>
				reject(
					new Error(timedOut ? "Request timed out." : "Request canceled."),
				),
			{ once: true },
		),
	);
	const timer = setTimeout(() => {
		timedOut = true;
		controller.abort();
	}, REQUEST_TIMEOUT);
	try {
		const data = validate(
			await Promise.race([
				fetch(url, {
					method: "GET",
					credentials: "omit",
					redirect: "error",
					signal: controller.signal,
				}).then(readJson),
